mapper.update:
UPDATE orders
status = #{status}, pay_status = #{payStatus}, checkout_time = #{checkoutTime}, cancel_time = #{cancelTime}, cancel_reason = #{cancelReason},
where id = #{id}

mapper.select:
SELECT * FROM orders


        AND user_id = #{userId}


        AND status = #{status}


        AND number LIKE CONCAT('%', #{number}, '%')


        AND phone LIKE CONCAT('%', #{phone}, '%')


        AND order_time >= #{beginTime}


        AND order_time <= #{endTime}


ORDER BY order_time DESC
